\begin{definition}
\label{def:5-32-extra-2}




Let $M$ be a smooth manifold. An immersed submanifold $S\subseteq M$ is
\emph{weakly embedded} if every smooth map $F:N\to M$ with image in $S$ is
smooth as an $S$-valued map.
\end{definition}

